{"path": "/tmp/sv-4bb00a6723004273868a05657695858a/RecipeCommunity/Components/Shared/StarRating.razor", "file_text": "@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= CurrentRating ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  title="Rate @star star(s)">
                ★
            </span>
        }
    </div>
    <span class="rating-info">
        @if (Rated)
        {
            <span class="text-success">Thanks! You rated @CurrentRating star(s).</span>
        }
        else
        {
            <span>@AverageRating.ToString("F1") avg (@RatingCount ratings) — Click to rate!</span>
        }
    </span>
</div>

@code {
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int CurrentRating { get; set; }
    private bool Rated { get; set; }

    protected override void OnParametersSet()
    {
        if (!Rated)
            CurrentRating = (int)Math.Round(AverageRating);
    }

    private void Rate(int stars)
    {
        CurrentRating = stars;
        Rated = true;
    }
}
"}

